    TenantId int, SchemaName nvarchar(20), TableName nvarchar(64),
    FieldName nvarchar(64), FieldPosition int, SqlType nvarchar(40),
    IsKey bit, IsRequired bit, IsIdentity bit, ShortDescription nvarchar(255)
);
