INSERT INTO cfg.DictionaryTableField
    (TenantId, DictionaryTableId, FieldName, FieldPosition, SqlType,
     IsKey, IsRequired, IsIdentity, IsCustomField, IsMasked, ShortDescription,
     CreatedBy)
SELECT s.TenantId, d.Id, s.FieldName, s.FieldPosition, s.SqlType,
       s.IsKey, s.IsRequired, s.IsIdentity, 0, 0, s.ShortDescription, N'SYSTEM'
FROM   #DictionaryField AS s
JOIN   cfg.DictionaryTable AS d
       ON  d.TenantId   = s.TenantId
       AND d.SchemaName = s.SchemaName
       AND d.TableName  = s.TableName;
GO
DROP TABLE #DictionaryField;
GO
